exercises.starter:
pub fn first_multiple(of: u32, above: u32) -> u32 {
    let mut n = above;
    let found = loop {
        if n % of == 0 {
            break;
        }
        n += 1;
    };
    found
}

exercises.tests:
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn finds_the_next_multiple() {
        assert_eq!(first_multiple(7, 50), 56);
    }
    #[test]
    fn already_a_multiple() {
        assert_eq!(first_multiple(7, 49), 49);
    }
}

exercises.solution:
pub fn first_multiple(of: u32, above: u32) -> u32 {
    let mut n = above;
    let found = loop {
        if n % of == 0 {
            break n;
        }
        n += 1;
    };
    found
}

exercises.starter:
pub fn summary(text: &str) -> String {
    let longest: &str = {
        let mut best = "";
        for line in text.lines() {
            if line.len() > best.len() {
                best = line;
            }
        }
    };
    format!("{longest} ({} lines)", text.lines().count())
}

exercises.tests:
